import { useState, useEffect } from "react";
import axios from "axios";
import { T, LEVELS, statusConfig, levelColors } from "./constants";
import Sidebar from "./Sidebar";
import ApplicationModal from "./ApplicationModal";

export default function AdminDashboard({ onLogout }) {
  const [apps, setApps] = useState([]);
  const [activeBranch, setActiveBranch] = useState("cairo");
  const [activeLevel, setActiveLevel] = useState("HSK 1");
  const [search, setSearch] = useState("");
  const [selectedApp, setSelectedApp] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // ── Fetch Data ─────────────────────────────────────────
  const fetchStudents = async () => {
    try {
      const response = await axios.get("http://localhost:8000/students");

      const formatted = response.data.map((s) => ({
        id: s.id,
        name: s.full_name,
        nid: s.national_number,
        phone: s.phone,
        email: s.email,
        level: s.level,
        branch: s.location?.toLowerCase().includes("cairo")
          ? "cairo"
          : "ainshams",
        mode: s.mode,
        date: new Date(s.created_at).toLocaleDateString(),
        status: s.status || "pending",
      }));

      setApps(formatted);
    } catch (err) {
      console.error("Fetch error:", err);
      setError("Failed to fetch students.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  // ── Handlers ──────────────────────────────────────────
  const changeStatus = (id, status) => {
    setApps((prev) =>
      prev.map((a) => (a.id === id ? { ...a, status } : a))
    );
    setSelectedApp((prev) =>
      prev?.id === id ? { ...prev, status } : prev
    );
  };

  const handleBranch = (key) => {
    setActiveBranch(key);
    setActiveLevel("HSK 1");
    setSearch("");
  };

  const handleLevel = (lv) => {
    setActiveLevel(lv);
    setSearch("");
  };

  // ── Derived Data ──────────────────────────────────────
  const levelApps = apps.filter(
    (a) => a.branch === activeBranch && a.level === activeLevel
  );

  const filtered = search
    ? levelApps.filter(
        (a) =>
          a.name.includes(search) ||
          a.phone.includes(search) ||
          a.email.toLowerCase().includes(search.toLowerCase()) ||
          a.nid.includes(search)
      )
    : levelApps;

  const stats = {
    total: apps.length,
    pending: apps.filter((a) => a.status === "pending").length,
    approved: apps.filter((a) => a.status === "approved").length,
    rejected: apps.filter((a) => a.status === "rejected").length,
  };

  const branchLabel =
    activeBranch === "cairo" ? "جامعة القاهرة" : "جامعة عين شمس";

  // ── Loading / Error ───────────────────────────────────
  if (loading) {
    return <div style={{ padding: "40px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ padding: "40px", color: "red" }}>
        {error}
      </div>
    );
  }

  // ── Styles (same as yours, shortened here for clarity) ──
  const s = {
    root: { display: "flex", minHeight: "100vh", direction: "rtl" },
    main: { flex: 1, display: "flex", flexDirection: "column" },
    content: { flex: 1, padding: "28px" },
    table: { width: "100%", borderCollapse: "collapse" },
    td: { padding: "10px" },
    th: { padding: "10px", fontWeight: "bold" },
  };

  const TABLE_HEADERS = [
    "#",
    "الاسم",
    "الهاتف",
    "البريد الإلكتروني",
    "طريقة الدراسة",
    "تاريخ التسجيل",
    "الحالة",
  ];

  // ── Render ────────────────────────────────────────────
  return (
    <div style={s.root}>
      <Sidebar
        apps={apps}
        activeBranch={activeBranch}
        activeLevel={activeLevel}
        onBranch={handleBranch}
        onLevel={handleLevel}
        onLogout={onLogout}
        open={sidebarOpen}
      />

      <div style={s.main}>
        <div style={s.content}>
          <h2>
            طلبات {activeLevel} — {branchLabel}
          </h2>

          <input
            placeholder="بحث..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />

          {filtered.length === 0 ? (
            <p>لا توجد بيانات</p>
          ) : (
            <table style={s.table}>
              <thead>
                <tr>
                  {TABLE_HEADERS.map((h) => (
                    <th key={h} style={s.th}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.map((app, idx) => (
                  <tr
                    key={app.id}
                    onClick={() => setSelectedApp(app)}
                    style={{ cursor: "pointer" }}
                  >
                    <td style={s.td}>{idx + 1}</td>
                    <td style={s.td}>{app.name}</td>
                    <td style={s.td}>{app.phone}</td>
                    <td style={s.td}>{app.email}</td>
                    <td style={s.td}>{app.mode}</td>
                    <td style={s.td}>{app.date}</td>
                    <td style={s.td}>
                      {statusConfig[app.status]?.label || app.status}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      <ApplicationModal
        app={selectedApp}
        onClose={() => setSelectedApp(null)}
        onStatusChange={changeStatus}
      />
    </div>
  );
}
